std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        result.begin(), result.end(), result.begin(),
        [this](std::size_t /*unused*/, double /*placeholder*/) { return 0.0; });
    for (std::size_t c = 0; c < cols_; ++c) {
        std::vector<double> column(rows_);
        for (std::size_t r = 0; r < rows_; ++r) {
            column[r] = at(r, c);
        }
        result[c] = std::accumulate(column.begin(), column.end(), 0.0);
    }
    return result;
}

